#!/usr/bin/env node
/**
 * Generates FE-Audiomind/src/config/fallback-policy.ts from default-policy.json.
 * Invoked by scripts/sync-default-policy.sh — do not edit output manually.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const inputPath = resolve(process.argv[2]);
const outputPath = resolve(process.argv[3]);

const policy = JSON.parse(readFileSync(inputPath, "utf-8"));
const serialized = JSON.stringify(policy, null, 2);

const contents = `/** Auto-generated by scripts/sync-default-policy.sh — do not edit manually */\nexport const FALLBACK_POLICY = ${serialized} as const\n`;

writeFileSync(outputPath, contents, "utf-8");
console.log(`Wrote ${outputPath}`);
